/**
 * Textures. Decorative overlays that fill their
 * nearest positioned ancestor. Geometry and ink live here; only the tunables
 * (image, size, opacity, blend) arrive as custom properties from the
 * component.
 *
 * Ink is the black/white occlusion model, not palette — the same exception
 * material.css takes. Palette comes from var(--echo-*) only, in the grain
 * field below.
 */
.echo-texture {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: var(--echo-texture-image);
  background-size: var(--echo-texture-size) var(--echo-texture-size);
  opacity: var(--echo-texture-opacity);
  mix-blend-mode: var(--echo-texture-blend);
}

.echo-texture[data-fixed] {
  position: fixed;
}

/* Ordered dither must never be smoothed — the cells are the point. */
.echo-texture--dither {
  image-rendering: pixelated;
}

/* Halftone and scanlines are pure CSS gradients; they ignore the image var. */
.echo-texture--halftone {
  background-image: radial-gradient(
    circle at center,
    color-mix(in oklab, var(--echo-cast-ink, black) calc(0.55 * var(--echo-shade, 1) * 100%), transparent) 46%,
    color-mix(in oklab, var(--echo-cast-ink, black) calc(0 * var(--echo-shade, 1) * 100%), transparent) 47%
  );
}

.echo-texture--scanlines {
  background-image: repeating-linear-gradient(
    0deg,
    color-mix(in oklab, var(--echo-cast-ink, black) calc(0.18 * var(--echo-shade, 1) * 100%), transparent) 0px,
    color-mix(in oklab, var(--echo-cast-ink, black) calc(0.18 * var(--echo-shade, 1) * 100%), transparent) 1px,
    transparent 1px,
    transparent var(--echo-texture-size)
  );
  background-size: auto;
}

/* ------------------------------------------------------------------ field */

.echo-grain-field {
  position: relative;
  overflow: hidden;
}

.echo-grain-field__bloom {
  position: absolute;
  inset: 0;
}

/*
 * The brand field. Echo has ONE seed accent by design, so the bloom is built
 * from stops of the derived accent ramp rather than fixed hues: a sky seed
 * gives a sky field, with nothing of any other seed left in it.
 */
.echo-grain-field[data-tone="accent"] .echo-grain-field__bloom {
  background:
    radial-gradient(70% 90% at 22% 28%, var(--echo-accent-3) 0%, transparent 58%),
    radial-gradient(60% 80% at 82% 18%, var(--echo-accent-2) 0%, transparent 55%),
    radial-gradient(80% 90% at 65% 95%, var(--echo-accent-5) 0%, transparent 60%),
    var(--echo-accent-6);
}

.echo-grain-field[data-tone="chassis"] .echo-grain-field__bloom {
  background:
    radial-gradient(70% 90% at 25% 75%, var(--echo-cap) 0%, transparent 60%),
    radial-gradient(60% 80% at 80% 30%, var(--echo-bloom, var(--echo-accent-6)) 0%, transparent 55%),
    radial-gradient(60% 70% at 50% 10%, var(--echo-cap-highlight) 0%, transparent 55%),
    var(--echo-surface);
}

/* The accent field is deep on either device, so what's written on it is the paper colour: on a dark device, the text it inherits. */
.echo-grain-field[data-tone="accent"] .echo-grain-field__content {
  color: var(--echo-paper-stock, currentColor);
}

/* Edge darkening — keeps overlaid text legible over a busy field. */
.echo-grain-field__vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(120% 120% at 50% 45%, transparent 55%, color-mix(in oklab, var(--echo-cast-ink, black) calc(0.35 * var(--echo-shade, 1) * 100%), transparent));
}

.echo-grain-field__content {
  position: relative;
}

.echo-textured {
  position: relative;
}

/**
 * Texture tiles, for the grain law: "nothing in Echo is ever a flat fill".
 *
 * Every tile is a self-contained SVG data-URI generated here at module load —
 * no network, no binary assets, nothing to copy alongside the component when
 * `echo-ui add` installs it. Pure functions over numbers: no browser globals at
 * module scope, so this is SSR-safe.
 */

/**
 * Recursive Bayer threshold matrix, side `n` (a power of two). Returns each of
 * the values 0..n²-1 exactly once, arranged so that thresholding against it
 * produces ordered dither rather than clumping.
 */
export function bayer(n: number): number[][] {
  if (n === 1) return [[0]];
  if (n < 1 || (n & (n - 1)) !== 0) {
    throw new RangeError(`bayer(n): n must be a power of two, got ${n}`);
  }
  const half = bayer(n / 2);
  const s = n / 2;
  const m: number[][] = Array.from({ length: n }, () => new Array<number>(n).fill(0));
  for (let y = 0; y < s; y++) {
    for (let x = 0; x < s; x++) {
      const v = half[y]![x]! * 4;
      m[y]![x] = v + 0;
      m[y]![x + s] = v + 2;
      m[y + s]![x] = v + 3;
      m[y + s]![x + s] = v + 1;
    }
  }
  return m;
}

const svgUri = (body: string, w: number, h: number) =>
  `data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='${w}' height='${h}'>${body}</svg>`,
  )}`;

/**
 * An ordered-dither tile: one cell per matrix entry, each filled at
 * `opacity = threshold / n²`. `tone` picks the ink — dark ink deepens a
 * surface, light ink lifts it.
 */
export function ditherUri(n = 8, tone: "dark" | "light" = "dark"): string {
  const m = bayer(n);
  const px = 2; // device px per cell
  const ink = tone === "dark" ? "0,0,0" : "255,255,255";
  let rects = "";
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const a = (m[y]![x]! / (n * n)).toFixed(3);
      rects += `<rect x='${x * px}' y='${y * px}' width='${px}' height='${px}' fill='rgba(${ink},${a})'/>`;
    }
  }
  const size = n * px;
  return svgUri(rects, size, size);
}

/** Fractal-noise (film-grain) tile. Higher frequency = finer grain. */
export function noiseUri(baseFrequency: number, octaves: number): string {
  return svgUri(
    `<filter id='n'><feTurbulence type='fractalNoise' baseFrequency='${baseFrequency}' numOctaves='${octaves}' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/>`,
    160,
    160,
  );
}

export const ditherTile = {
  dark: ditherUri(8, "dark"),
  light: ditherUri(8, "light"),
} as const;

export const noiseTile = {
  /** Surface grain — the whisper that keeps a panel from reading as flat fill. */
  fine: noiseUri(0.9, 2),
  /** Marketing grain — the airbrushed spray on a brand field. */
  coarse: noiseUri(0.55, 3),
} as const;

/**
 * Textures — the grain law as a set of composable overlays: ordered DITHER, film-grain NOISE, HALFTONE dots, SCANLINES, and
 * the GRAIN FIELD they all descend from.
 *
 * Nothing in Echo is ever a flat fill. These are also the practical cure for
 * gradient banding on the dark chassis — a dither or grain pass over a large
 * soft gradient kills the posterised rings that dark surfaces show.
 *
 * Every overlay is decorative: aria-hidden, pointer-events: none, absolutely
 * filling its nearest positioned ancestor. Tunables ride as CSS custom
 * properties (the sanctioned exception to the no-inline-styles rule, same as
 * the Loader dot and the Tabs indicator); no literal values in `style`.
 */
import type { CSSProperties, ReactNode } from "react";
import { ditherTile, noiseTile } from "./tiles";
import "./textures.css";

type Blend = CSSProperties["mixBlendMode"];

interface OverlayProps {
  /** Layer opacity. Each texture ships the weight it is usually right at. */
  opacity?: number;
  /** Compositing mode against the surface below. */
  blend?: Blend;
  /** Pin to the viewport instead of the positioned ancestor. Default false. */
  fixed?: boolean;
  className?: string;
}

function overlayVars(
  image: string | undefined,
  size: string,
  opacity: number,
  blend: Blend,
): CSSProperties {
  // Halftone and scanlines draw themselves from CSS gradients, so they pass no
  // image var at all rather than an empty one.
  return {
    ...(image ? { "--echo-texture-image": image } : null),
    "--echo-texture-size": size,
    "--echo-texture-opacity": opacity,
    "--echo-texture-blend": blend,
  } as CSSProperties;
}

function Overlay({
  kind,
  vars,
  fixed,
  className,
}: {
  kind: string;
  vars: CSSProperties;
  fixed?: boolean;
  className?: string;
}) {
  return (
    <div
      className={["echo-texture", `echo-texture--${kind}`, className].filter(Boolean).join(" ")}
      data-fixed={fixed ? "" : undefined}
      aria-hidden="true"
      style={vars}
    />
  );
}

export interface DitherProps extends OverlayProps {
  /** Ink colour: dark deepens the surface, light lifts it. Default "dark". */
  tone?: "dark" | "light";
  /** Tile scale multiplier. 1 = a 16px tile. */
  scale?: number;
}

/** Ordered-dither overlay — the retro/print texture. Best over gradients and glows. */
export function Dither({
  opacity = 0.22,
  blend = "overlay",
  tone = "dark",
  scale = 1,
  fixed,
  className,
}: DitherProps = {}) {
  const size = `${16 * scale}px`;
  const uri = tone === "dark" ? ditherTile.dark : ditherTile.light;
  return (
    <Overlay
      kind="dither"
      vars={overlayVars(`url("${uri}")`, size, opacity, blend)}
      fixed={fixed}
      className={className}
    />
  );
}

export interface NoiseProps extends OverlayProps {
  /** "fine" for product surfaces, "coarse" for marketing fields. */
  grain?: "fine" | "coarse";
  /** Tile size in px. Larger = softer, more airbrushed. */
  size?: number;
}

/** Fractal-noise grain — the airbrushed, organic texture. */
export function Noise({
  opacity = 0.05,
  blend = "soft-light",
  grain = "fine",
  size = 200,
  fixed,
  className,
}: NoiseProps = {}) {
  const uri = grain === "fine" ? noiseTile.fine : noiseTile.coarse;
  return (
    <Overlay
      kind="noise"
      vars={overlayVars(`url("${uri}")`, `${size}px`, opacity, blend)}
      fixed={fixed}
      className={className}
    />
  );
}

export interface HalftoneProps extends OverlayProps {
  /** Dot pitch in px. */
  cell?: number;
}

/** Print/CRT halftone — the same DNA as the device dot-matrix, as a texture. */
export function Halftone({
  opacity = 0.4,
  blend = "multiply",
  cell = 4,
  fixed,
  className,
}: HalftoneProps = {}) {
  return (
    <Overlay
      kind="halftone"
      vars={overlayVars(undefined, `${cell}px`, opacity, blend)}
      fixed={fixed}
      className={className}
    />
  );
}

export interface ScanlinesProps extends OverlayProps {
  /** Line pitch in px. */
  gap?: number;
}

/** Scanlines — the CRT register, for anything pretending to be a screen. */
export function Scanlines({
  opacity = 0.35,
  blend = "multiply",
  gap = 3,
  fixed,
  className,
}: ScanlinesProps = {}) {
  return (
    <Overlay
      kind="scanlines"
      vars={overlayVars(undefined, `${gap}px`, opacity, blend)}
      fixed={fixed}
      className={className}
    />
  );
}

export interface GrainFieldProps {
  /**
   * Which ramp blooms. "accent" is the brand field (the seed accent, whatever
   * it is); "chassis" is the quiet neutral field for product backgrounds.
   */
  tone?: "accent" | "chassis";
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

/**
 * GrainField — the brand surface: a soft airbrushed bloom in the accent ramp,
 * two scales of spray grain, and an edge darkening pass that keeps overlaid
 * text legible. This is the marketing/brand texture; product surfaces keep
 * their own matte speckle and take only a whisper of `Noise`.
 */
export function GrainField({ tone = "accent", className, style, children }: GrainFieldProps) {
  return (
    <div
      className={["echo-grain-field", className].filter(Boolean).join(" ")}
      data-tone={tone}
      style={style}
    >
      <div className="echo-grain-field__bloom" aria-hidden="true" />
      <Noise grain="coarse" size={180} opacity={0.5} blend="soft-light" />
      <Noise grain="coarse" size={300} opacity={0.28} blend="overlay" />
      <div className="echo-grain-field__vignette" aria-hidden="true" />
      <div className="echo-grain-field__content">{children}</div>
    </div>
  );
}

export interface TexturedProps {
  dither?: boolean;
  noise?: boolean;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

/** Wrap any content and stack the default treatment (grain + dither) over it. */
export function Textured({
  dither = true,
  noise = true,
  className,
  style,
  children,
}: TexturedProps) {
  return (
    <div className={["echo-textured", className].filter(Boolean).join(" ")} style={style}>
      {children}
      {noise ? <Noise opacity={0.06} /> : null}
      {dither ? <Dither opacity={0.16} /> : null}
    </div>
  );
}

export { Dither, Noise, Halftone, Scanlines, GrainField, Textured } from "./textures";
export type {
  DitherProps,
  NoiseProps,
  HalftoneProps,
  ScanlinesProps,
  GrainFieldProps,
  TexturedProps,
} from "./textures";
export { bayer, ditherUri, noiseUri, ditherTile, noiseTile } from "./tiles";
